<script setup lang="ts">
import { computed, onMounted, onUnmounted, reactive, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { useAccount } from '../stores/account'
import { passwordIssue, safeReturnPath } from '../account/rules'
import TurnstileChallenge from '../components/TurnstileChallenge.vue'
import { securityMeta, type SecurityMeta } from '../security/api'
import { AccountError } from '../account/api'
const route=useRoute(),router=useRouter(),account=useAccount()
const registering=computed(()=>route.name==='register'),returnTo=computed(()=>safeReturnPath(route.query.redirect))
const security=ref<SecurityMeta|null>(null),securityError=ref(''),challengeToken=ref(''),challengeShown=ref(false),challengeReset=ref(0)
const form=reactive({email:'',name:'',password:'',confirm:''}),showPassword=ref(false),error=ref(''),touched=ref(false)
let alive=true
async function loadSecurity(){securityError.value='';security.value=null;try{security.value=await securityMeta();if(registering.value&&security.value.turnstileEnabled)challengeShown.value=true}catch(e){securityError.value=(e as Error).message}}
const passwordHint=computed(()=>registering.value&&touched.value?passwordIssue(form.password):'')
const switchTo=computed(()=>({path:registering.value?'/login':'/register',query:{...(returnTo.value!=='/account'?{redirect:returnTo.value}:{}),...(route.query.guide==='1'?{guide:'1'}:{})}}))
async function submit(){if(account.busy||!security.value)return;if(registering.value&&security.value.turnstileEnabled&&!challengeToken.value){error.value='请先完成安全验证。';return}const origin=route.fullPath,wasRegistering=registering.value,destination=returnTo.value,usedToken=challengeToken.value;error.value='';touched.value=true;if(registering.value){const problem=passwordIssue(form.password);if(problem){error.value=problem;return}if(form.password!==form.confirm){error.value='两次输入的密码不一致。';return}}
 try{if(registering.value)await account.register(form.email,form.name,form.password,challengeToken.value||undefined);else await account.login(form.email,form.password,challengeToken.value||undefined);challengeToken.value='';form.password='';form.confirm='';if(!alive||route.fullPath!==origin)return;await router.replace(wasRegistering&&destination==='/account'?{path:'/account',query:{welcome:'1'}}:destination)}catch(e){error.value=(e as Error).message;form.password='';form.confirm='';if(usedToken){challengeToken.value='';challengeReset.value++}if(e instanceof AccountError&&['CHALLENGE_REQUIRED','CHALLENGE_INVALID','CHALLENGE_EXPIRED','CHALLENGE_REPLAY'].includes(e.code||'')){challengeShown.value=true;challengeToken.value='';if(!usedToken)challengeReset.value++;if(!security.value?.turnstileEnabled)await loadSecurity()}}}
watch(()=>route.name,()=>{challengeToken.value='';challengeShown.value=Boolean(registering.value&&security.value?.turnstileEnabled);challengeReset.value++;form.password='';form.confirm='';error.value='';touched.value=false;showPassword.value=false})
onMounted(async()=>{await loadSecurity();await account.refresh();if(account.profile){if(!registering.value&&returnTo.value.startsWith('/review')&&!account.isAdmin)error.value='当前账户没有管理员权限；如需切换身份，请使用授权账户登录。';else void router.replace(returnTo.value)}})
onUnmounted(()=>{alive=false;form.password='';form.confirm=''})
</script>
<template><main class="auth-system-page"><section class="auth-visual"><div class="auth-image-frame"><img src="/botanical/ginkgo-biloba-hero.webp" alt="银杏叶片，植物图鉴插图，不作为鉴定证据"/><span class="auth-image-credit">GINKGO BILOBA · 图鉴插图</span></div><p class="section-kicker">VIRIDEXA / YOUR NEXT DISCOVERY</p><span class="auth-story-mark" aria-hidden="true">V</span><h1>让每一份好奇，<br/><em>都有一个开始。</em></h1><p>认识植物、探索关系、追踪来源。<br/>以自己的身份，走进植序的研究空间。</p><div class="auth-story-note"><span aria-hidden="true">↗</span><p><strong>探索，不需要门槛。</strong><br/>公开目录与基础图谱可直接浏览；Agent 和科研实验台登录后使用。</p></div><RouterLink to="/explore">先浏览植物图鉴 →</RouterLink></section>
<section class="auth-form-card" :aria-labelledby="registering?'register-title':'login-title'"><nav class="auth-tabs" aria-label="账户入口"><RouterLink :class="{active:!registering}" :to="registering?switchTo:{path:'/login',query:route.query}">登录</RouterLink><RouterLink :class="{active:registering}" :to="registering?{path:'/register',query:route.query}:switchTo">注册</RouterLink></nav><p class="section-kicker">{{registering?'START GROWING':'WELCOME BACK'}}</p><h2 :id="registering?'register-title':'login-title'">{{registering?'你好，新的探索者。':'欢迎回来，探索者。'}}</h2><p v-if="!registering&&route.query.redirect" class="auth-access-note" role="status">继续使用研究功能前，请先登录。登录后将返回刚才的研究页面。</p><p class="auth-intro">{{registering?'创建公众账户，使用喜欢的昵称就好。':'使用邮箱登录你的植序账户。'}}</p><p v-if="securityError" class="auth-error" role="alert">{{securityError}} <button type="button" class="auth-security-retry" @click="loadSecurity">重新读取安全配置</button></p><p v-else-if="security?.turnstileMode==='test'" class="auth-hint">Cloudflare 测试密钥仅用于检查集成流程，不能证明真实生产挑战保护已生效。</p><p v-else-if="security?.turnstileMode==='disabled'" class="auth-hint">本地环境未启用 Cloudflare 验证；这不代表真实部署已获得该项保护。</p><p v-if="error" class="auth-error" role="alert">{{error}}</p><form @submit.prevent="submit"><label v-if="registering" for="account-name">你的昵称<input id="account-name" v-model="form.name" autocomplete="nickname" required minlength="2" maxlength="60" placeholder="例如：小树同学" :disabled="account.busy"/></label><label for="account-email">邮箱<input id="account-email" v-model="form.email" type="email" autocomplete="username" required maxlength="254" placeholder="you@example.com" :disabled="account.busy"/></label><div class="auth-form-field"><label for="account-password">密码</label><div class="auth-password-field"><input id="account-password" v-model="form.password" :type="showPassword?'text':'password'" :autocomplete="registering?'new-password':'current-password'" required maxlength="200" :aria-describedby="registering?'password-hint':undefined" placeholder="输入你的密码" :disabled="account.busy" @blur="touched=true"/><button type="button" :aria-pressed="showPassword" :aria-label="showPassword?'隐藏密码':'显示密码'" @click="showPassword=!showPassword">{{showPassword?'隐藏':'显示'}}</button></div></div><p v-if="registering" id="password-hint" class="auth-hint" :class="{'auth-hint-error':passwordHint}">{{passwordHint||'12–72 个 UTF-8 字节，推荐使用独立的长密码；中文通常每字占 3 字节。'}}</p><label v-if="registering" for="account-confirm">再次输入密码<input id="account-confirm" v-model="form.confirm" :type="showPassword?'text':'password'" autocomplete="new-password" required maxlength="200" placeholder="再输入一次，避免手误" :disabled="account.busy"/></label><TurnstileChallenge v-if="challengeShown&&security?.turnstileEnabled" :site-key="security.siteKey" :action="registering?'register':'login'" :reset-key="challengeReset" @token="challengeToken=$event" @error="challengeToken=''"/><button class="auth-submit" :disabled="account.busy||!security">{{account.busy?'正在安全连接…':registering?'注册并登录':'登录账户'}} <span aria-hidden="true">↗</span></button></form><p class="auth-privacy">邮箱用于登录，不会展示在公开植物或图谱中。当前未启用邮箱验证及邮件找回，请使用自己可管理的邮箱并妥善保存密码。</p><details class="auth-how" :open="route.query.guide==='1'"><summary>第一次使用？登录注册指南</summary><ol><li><strong>选择「注册」</strong><span>填写昵称、邮箱和独立密码，再确认一次密码。</span></li><li><strong>注册成功，自动登录</strong><span>进入「我的账户」，查看当前身份与研究入口。</span></li><li><strong>从好奇开始探索</strong><span>访客浏览目录与基础图谱；登录后使用 Agent 和科研实验台。普通账户不包含科学审核或管理权限。</span></li></ol><RouterLink v-if="!registering" :to="switchTo">开始注册公众账户 →</RouterLink><p v-else>遇到重复邮箱？切换到登录；密码输入错误时可以重新尝试。</p></details><p v-if="!registering" class="auth-admin-note">管理员也从这里登录，系统按账户的真实权限开放审核台。</p></section></main></template>
